def tiles(items):
    cells = [[Paragraph(f'<font name="Poppins-Bold" size="16.5" color="#1f4e3d">{a}</font>', ST('tn', leading=20)), Paragraph(t, ST('tl', fontSize=8.6, leading=10.8))] for a, t in items]; k = len(items)
    return [Table([cells], colWidths=[CW / k] * k, style=[('BACKGROUND', (0, 0), (-1, -1), CREAM), ('LINEABOVE', (0, 0), (-1, 0), 1.6, GREEN), ('LINEAFTER', (0, 0), (-2, -1), 2.5, colors.white), ('VALIGN', (0, 0), (-1, -1), 'TOP'), ('TOPPADDING', (0, 0), (-1, -1), 6), ('BOTTOMPADDING', (0, 0), (-1, -1), 8), ('LEFTPADDING', (0, 0), (-1, -1), 7), ('RIGHTPADDING', (0, 0), (-1, -1), 6)]), Spacer(1, 4)]
def table(rows, widths, bold_rows=(), cap=None, align_right_from=1):
    data = [[Paragraph(str(c), HEAD) for c in rows[0]]] + [[Paragraph(str(c), CELLB if i in bold_rows else CELL) for c in r] for i, r in enumerate(rows[1:])]
    sty = [('BACKGROUND', (0, 0), (-1, 0), GREEN), ('LINEBELOW', (0, 1), (-1, -1), 0.5, RULE), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), 3.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 4.5), ('LEFTPADDING', (0, 0), (-1, -1), 5), ('RIGHTPADDING', (0, 0), (-1, -1), 4)]
    sty += [('BACKGROUND', (0, i), (-1, i), CREAM) for i in range(2, len(data), 2)]
    out = [Table(data, colWidths=[w * mm for w in widths], style=sty, repeatRows=1), Spacer(1, 3)]
    return out + ([Paragraph(cap, CAP)] if cap else [Spacer(1, 6)])
def fig(name, cap, w=1.0, keep=True):
    path = f'{ROOT}/outputs/{name}'; iw, ih = PILImage.open(path).size; ww = CW * w; fl = [Image(path, width=ww, height=ww * ih / iw), Spacer(1, 3), Paragraph(cap, CAP)]
    return [KeepTogether(fl)] if keep else fl
def flow(steps):
    cells = [[Paragraph(f'<font name="Carlito-Bold" color="white" size="9.4">{a}</font><br/><font color="white" size="7.8">{t}</font>', ST('fl', leading=10.2, alignment=1)) for a, t in row] for row in steps]; k = len(steps[0]); gap = 3 * mm; cw = (CW - gap * (k - 1)) / k
    data, sty = [], [('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), 7), ('BOTTOMPADDING', (0, 0), (-1, -1), 8)]
    for r, row in enumerate(cells):
        line = []
        for c, cell in enumerate(row):
            line.append(cell); sty.append(('BACKGROUND', (2 * c, 2 * r), (2 * c, 2 * r), GOLD if (r == len(cells) - 1 and c == k - 1) else GREEN)); sty.append(('ROUNDEDCORNERS', [4, 4, 4, 4]))
            if c < k - 1: line.append('')
        data.append(line)
        if r < len(cells) - 1: data.append([''] * (2 * k - 1))
    return [Table(data, colWidths=[x for c in range(k) for x in ([cw, gap] if c < k - 1 else [cw])], rowHeights=[None if i % 2 == 0 else 3 * mm for i in range(len(data))], style=sty), Spacer(1, 4)]

