S += section('8', 'Model predictions and case studies', 'Dashboard · SHAP · Translated radar')
S += [P("The screenshots are from the Streamlit app (<font name='Carlito-Italic'>app/shadow_squad.py</font>), which reads the Parquet lake: choose a league, an elite club, a season and a departing starter. It shows the ranked list, what the club really did, a radar (starter's actual numbers, candidate raw, candidate translated into the club), a SHAP waterfall for the chosen candidate, and market values. The cases were picked by rule, not by hand: the three unseen events with the best rank for the real signing (ties broken by the larger fee), and the unseen event where a real signing was ranked worst."),
      P(f"Across all unseen events the scores that move the ranking most are {', '.join(k.replace('_', ' ').replace('log value', 'market value').replace('age num', 'age') for k in list(p6['shap_global']['mean_abs_shap'])[::-1][:4])} (mean absolute SHAP).")]
S += fig('figs/p6_shap_global.png', 'Figure 20. Mean absolute SHAP value of each score on unseen events.', 0.62)
NICE = {'log_value': 'market value', 'value_gap': 'closeness in value to the starter', 'sim_translated': 'translated similarity', 'traj_sim': 'trajectory similarity', 'pipeline_rank': 'club pipeline rank', 'club_taste': 'club taste', 'hazard': 'move-up hazard', 'age_num': 'age', 'composite_perf_index': 'composite index'}
def case(c, k):
    pcts = {f: min(v, 0.99) for f, v in c['signed_feature_percentile_in_pool'].items()}; pcts['value_gap'] = min(1 - c['signed_feature_percentile_in_pool']['value_gap'], 0.99); pcts.pop('age_num', None); srt = sorted(pcts.items(), key=lambda kv: kv[1]); pick = srt[:3] if c['kind'] == 'miss' else srt[-3:][::-1]
    desc = ', '.join(f"{NICE[f]} (better than {100 * v:.0f}% of the pool)" for f, v in pick); fee = 'fee not recorded' if c['fee'] is None else ('free or undisclosed fee' if c['fee'] == 0 else f"EUR {c['fee'] / 1e6:.1f}m")
    head = f"<b>{esc(c['club'])} {c['season']}-{str(c['season'] + 1)[2:]}: {esc(c['starter'])} ({c['position']}) replaced by {esc(c['signed'])} from {esc(c['from'])} ({fee}).</b> "
    if c['kind'] == 'hit': body = f"The engine ranked him {c['rank']} of {c['pool']} candidates. His strongest scores were {desc}. The waterfall shows which scores carried him there, and the radar how his numbers sit against the starter's once translated into the club."
    else: body = f"The engine ranked him {c['rank']} of {c['pool']}, almost last. His weakest scores were {desc}. He was valued at EUR {c['signed_value'] / 1e6:.1f}m and the starter he replaced at EUR {c['starter_value'] / 1e6:.1f}m. On the scores the engine uses he looked nothing like the man he replaced, so nothing pointed to him; whatever the club saw is not in the data."
    out = [P(head + body)] + fig(f"screens/{c['tag']}_list.png", f"Figure {k}a. Ranked list for this event (top 10), from the dashboard.", 0.86 if c['kind'] == 'hit' else 0.72, keep=False) + fig(f"screens/{c['tag']}_panels.png", f"Figure {k}b. {esc(c['signed'])}: translated radar, SHAP waterfall and value panel.", 0.74 if c['kind'] == 'hit' else 0.56, keep=False)
    return [KeepTogether(([P('A miss', H2)] if c['kind'] == 'miss' else []) + out[:4]), KeepTogether(out[4:])]
k = 21
for c in [c for c in p6['cases'] if c['kind'] == 'hit']: S += case(c, k); k += 1
for c in [c for c in p6['cases'] if c['kind'] == 'miss']: S += case(c, k); k += 1

